import JSZip from 'jszip'
const headers=['id','description','code','native_line_id','scheduled_cents','completed_cents','stored_cents','actual_cents','paid_cents','retainage_cents','collected_cents','client_retainage_cents','billed_tax_cents']
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;')
const row=(n,values)=>`<row r="${n}">${values.map((value,i)=>{const at=String.fromCharCode(65+i)+n;if(value&&typeof value==='object')return `<c r="${at}"><f>${escape(value.formula)}</f>${value.cache===undefined?'':`<v>${value.cache}</v>`}</c>`;return `<c r="${at}" t="inlineStr"><is><t>${escape(value)}</t></is></c>`}).join('')}</row>`
export async function openingInput(job,{missingCache=false,mismatch=false,tag='synthetic-plinth-opening-1'}={}){
 const zip=new JSZip(),ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'
 zip.file('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'+[1,2].map(n=>`<Override PartName="/xl/worksheets/sheet${n}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')+'</Types>')
 zip.file('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>')
 zip.file('xl/workbook.xml',`<workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Opening" sheetId="1" r:id="rId1"/><sheet name="Notes" sheetId="2" r:id="rId2"/></sheets></workbook>`)
 zip.file('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+[1,2].map(n=>`<Relationship Id="rId${n}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${n}.xml"/>`).join('')+'</Relationships>')
 const values=[headers,[tag+'-frame','Opening framing','FRAME','quote:frame',220000,{formula:'40000+4000',...(missingCache?{}:{cache:44000})},0,20000,15000,1000,27500,2200,4000],[tag+'-labor','Opening labor','LABOR','quote:labor',110000,11000,0,8000,5000,0,5500,550,1000],[tag+'-invalid','Unresolved source code','INVALID','quote:missing',0,0,0,500,0,0,0,0,0]]
 zip.file('xl/worksheets/sheet1.xml',`<worksheet xmlns="${ns}"><sheetData>${values.map((values,i)=>row(i+1,values)).join('')}</sheetData></worksheet>`)
 zip.file('xl/worksheets/sheet2.xml',`<worksheet xmlns="${ns}"><sheetData>${row(1,['Notes'])}${row(2,['Historical source; no previous approvals are invented'])}</sheetData></worksheet>`)
 // Independently supplied ledger values and column order; never computed from parsed source rows.
 const ledgerHeaders=['id','code','native_line_id','description','actual_cents','paid_cents','retainage_cents','scheduled_cents','completed_cents','stored_cents','collected_cents','client_retainage_cents','billed_tax_cents']
 const ledgerRows=[ledgerHeaders,['ledger-frame','06-100','quote:frame','Supplied ledger framing',mismatch?20001:20000,15000,1000,220000,44000,0,27500,2200,4000],['ledger-labor','01-100','quote:labor','Supplied ledger labor',8000,5000,0,110000,11000,0,5500,550,1000]]
 const csv=ledgerRows.map(row=>row.map(v=>'"'+v+'"').join(',')).join('\r\n')+'\r\n'
 const mapping={purpose:'opening',sheet:'Opening',currency:'USD',columns:Object.fromEntries(headers.map((h,i)=>[h,String.fromCharCode(65+i)])),codes:{FRAME:'06-100',LABOR:'01-100'},duplicates:'reject',reviewed_formulas:true,excluded_rows:{'4':'Invalid code held for explicit source correction'}}
 return {name:tag+'.xlsx',base64:await zip.generateAsync({type:'base64',compression:'DEFLATE'}),title:'Reviewed opening workbook',job_id:job.id,expected_version:job.version,as_of:'2026-10-01',posting_period:'2026-10',mapping,ledger_reviewed:true,ledger:{name:tag+'-ledger.csv',base64:Buffer.from(csv).toString('base64'),mapping:{sheet:'CSV',currency:'USD',columns:Object.fromEntries(ledgerHeaders.map((h,i)=>[h,String.fromCharCode(65+i)])),codes:{'06-100':'06-100','01-100':'01-100'},duplicates:'reject',reviewed_formulas:false,excluded_rows:{}}}}
}
